  return value.flatMap((item, index) => {
    if (typeof item !== 'string') {
      addFieldError(fields, `${field}.${index}`, `${field}.${index} must be a string`);
      return [];
    }

    const trimmed = item.trim();

    if (!trimmed) {
      addFieldError(fields, `${field}.${index}`, `${field}.${index} is required`);
      return [];
    }

    if (options.itemMaxLength && trimmed.length > options.itemMaxLength) {
      addFieldError(
        fields,
        `${field}.${index}`,
        `${field}.${index} must be at most ${options.itemMaxLength} characters`
      );
      return [];
    }

    return [trimmed];
  });
}

