          <p className="font-mono text-sm leading-7 text-[#C7CAD5]">
            Your Pre-Sale project draft has been saved and submitted for setup
            review.
          </p>
        </div>
      ) : null}
    </CardView>
  );
}

function WizardActions({
  onBack,
  onSubmit,
  isSaving,
  nextLabel = 'Continue',
}: {
  onBack: () => void;
  onSubmit?: () => void;
  isSaving: boolean;
  nextLabel?: string;
}) {
  return (
    <div className="flex w-full items-center justify-between pt-4">
      <CustomButton
        type="button"
        variant="canceled"
        className="flex h-11 w-32 items-center justify-center gap-2 text-sm"
        onClick={onBack}
        disabled={isSaving}
      >
        <ArrowLeft size={20} />
        Back
      </CustomButton>
      <CustomButton
        type={onSubmit ? 'button' : 'submit'}
        variant="filled"
        className="flex h-11 w-fit items-center justify-center text-sm"
        onClick={onSubmit}
        disabled={isSaving}
      >
        {isSaving ? 'Saving…' : nextLabel}
      </CustomButton>
    </div>
  );
}
