type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
  milestones?: ConstructionMilestone[];
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildVisibilityMap(milestones: ConstructionMilestone[]) {
  const map = new Map<string, boolean>();

  milestones.forEach((milestone) => {
    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => {
        map.set(
          nodeName,
          component.visibleWhenCompleted === false
            ? !milestone.completed
            : milestone.completed
        );
      });
    });
  });

  return map;
}

function Model({
  modelUrl,
  milestones = [],
}: {
  modelUrl: string;
  milestones?: ConstructionMilestone[];
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const originalVisibility = useRef(new Map<Object3D, boolean>());
  const clonedMaterials = useRef<MeshStandardMaterial[]>([]);
  const visibilityByNodeName = useMemo(
    () => buildVisibilityMap(milestones),
    [milestones]
  );
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(gltf.scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [gltf.scene]);

  useEffect(() => {
    gltf.scene.traverse((object) => {
      if (!originalVisibility.current.has(object)) {
        originalVisibility.current.set(object, object.visible);
      }

      const explicitVisibility = visibilityByNodeName.get(object.name);
      object.visible = explicitVisibility ?? originalVisibility.current.get(object) ?? true;

      if (isMesh(object)) {
        object.castShadow = true;
        object.receiveShadow = true;

        const material = Array.isArray(object.material)
          ? object.material[0]
          : object.material;

        if (material && !(material instanceof MeshStandardMaterial)) {
          const clonedMaterial = new MeshStandardMaterial({
            color: new Color('#d8d8d8'),
            metalness: 0.25,
            roughness: 0.55,
          });
          object.material = clonedMaterial;
          clonedMaterials.current.push(clonedMaterial);
        } else if (material instanceof MeshStandardMaterial) {
          const clonedMaterial = material.clone();
          object.material = clonedMaterial;
          clonedMaterials.current.push(clonedMaterial);
        }

        const nextMaterial = Array.isArray(object.material)
          ? object.material[0]
          : object.material;

        if (nextMaterial instanceof MeshStandardMaterial) {
          const isVisible = object.visible;
          nextMaterial.color.set(isVisible ? '#24FF8E' : '#8A89A2');
          nextMaterial.opacity = isVisible ? 1 : 0.1;
          nextMaterial.transparent = !isVisible;
          nextMaterial.emissive.set(isVisible ? '#0c5a34' : '#000000');
          nextMaterial.emissiveIntensity = isVisible ? 0.35 : 0;
        }
      }
    });

    bounds.refresh(gltf.scene).fit();

    return () => {
      clonedMaterials.current.forEach((material) => material.dispose());
      clonedMaterials.current = [];
    };
  }, [bounds, gltf.scene, visibilityByNodeName]);

  return <primitive object={gltf.scene} position={modelOffset} />;
}

