import {
  Bounds,
  Environment,
  Html,
  OrbitControls,
  useBounds,
  useGLTF,
} from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import { Suspense, useEffect, useMemo, useRef, useState } from 'react';
import {
  Box3,
  Color,
  MeshStandardMaterial,
  Vector3,
  type Mesh,
  type Object3D,
} from 'three';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
  milestones?: ConstructionMilestone[];
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildVisibilityMap(milestones: ConstructionMilestone[]) {
  const map = new Map<string, boolean>();

  milestones.forEach((milestone) => {
    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => {
        map.set(
          nodeName,
          component.visibleWhenCompleted === false
            ? !milestone.completed
            : milestone.completed
        );
      });
    });
  });

  return map;
}

function Model({
  modelUrl,
  milestones = [],
}: {
  modelUrl: string;
  milestones?: ConstructionMilestone[];
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const originalVisibility = useRef(new Map<Object3D, boolean>());
  const clonedMaterials = useRef<MeshStandardMaterial[]>([]);
  const visibilityByNodeName = useMemo(
    () => buildVisibilityMap(milestones),
    [milestones]
  );
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(gltf.scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [gltf.scene]);

  useEffect(() => {
    gltf.scene.traverse((object) => {
      if (!originalVisibility.current.has(object)) {
        originalVisibility.current.set(object, object.visible);
      }

      const explicitVisibility = visibilityByNodeName.get(object.name);
      object.visible =
        explicitVisibility ?? originalVisibility.current.get(object) ?? true;

      if (isMesh(object)) {
        object.castShadow = true;
        object.receiveShadow = true;

        const material = Array.isArray(object.material)
          ? object.material[0]
          : object.material;

        if (material && !(material instanceof MeshStandardMaterial)) {
          const clonedMaterial = new MeshStandardMaterial({
            color: new Color('#d8d8d8'),
            metalness: 0.25,
            roughness: 0.55,
          });
          object.material = clonedMaterial;
          clonedMaterials.current.push(clonedMaterial);
        } else if (material instanceof MeshStandardMaterial) {
          const clonedMaterial = material.clone();
          object.material = clonedMaterial;
          clonedMaterials.current.push(clonedMaterial);
        }

        const nextMaterial = Array.isArray(object.material)
          ? object.material[0]
          : object.material;

        if (nextMaterial instanceof MeshStandardMaterial) {
          const isVisible = object.visible;
          nextMaterial.color.set(isVisible ? '#24FF8E' : '#8A89A2');
          nextMaterial.opacity = isVisible ? 1 : 0.1;
          nextMaterial.transparent = !isVisible;
          nextMaterial.emissive.set(isVisible ? '#0c5a34' : '#000000');
          nextMaterial.emissiveIntensity = isVisible ? 0.35 : 0;
        }
      }
    });

    bounds.refresh(gltf.scene).fit();

    return () => {
      clonedMaterials.current.forEach((material) => material.dispose());
      clonedMaterials.current = [];
    };
  }, [bounds, gltf.scene, visibilityByNodeName]);

  return <primitive object={gltf.scene} position={modelOffset} />;
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

export function DigitalTwinModelViewer({
  modelUrl,
  title,
  milestones,
}: DigitalTwinModelViewerProps) {
  const [showGroundPlane, setShowGroundPlane] = useState(true);
  const [showKeyLight, setShowKeyLight] = useState(true);

  return (
    <section className="overflow-hidden rounded-[28px] border border-card-border bg-card-bg shadow-2xl backdrop-blur-xl">
      <div className="flex flex-col gap-1 border-b border-card-border px-6 py-5 md:flex-row md:items-center md:justify-between">
        <div>
          <p className="text-xs uppercase tracking-[0.35em] text-primary">
            AI-Digital Twin
          </p>
          <h1 className="chakra-petch mt-2 text-3xl font-bold text-white md:text-4xl">
            {title}
          </h1>
        </div>
      </div>

      <div
        className={`relative h-[520px] ${showGroundPlane ? 'bg-[#6f6f6f]' : 'bg-[#808080]'}`}
      >
        <div className="absolute right-4 top-4 z-10 flex flex-col gap-2 rounded-2xl border border-white/20 bg-[#0C0C0D]/75 p-3 text-xs text-gray-200 shadow-xl backdrop-blur-xl">
          <label className="flex items-center justify-between gap-3">
            <span>Ground</span>
            <input
              type="checkbox"
              checked={showGroundPlane}
              onChange={(event) => setShowGroundPlane(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
          <label className="flex items-center justify-between gap-3">
            <span>Light</span>
            <input
              type="checkbox"
              checked={showKeyLight}
              onChange={(event) => setShowKeyLight(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
        </div>

        <Canvas
          camera={{ position: [5, 4, 8], fov: 45 }}
          shadows
          gl={{ antialias: true }}
        >
          <color
            attach="background"
            args={[showGroundPlane ? '#6f6f6f' : '#808080']}
          />
          <ambientLight intensity={0.35} />
          <hemisphereLight args={['#ffffff', '#303030', 0.7]} />
          {showKeyLight ? (
            <directionalLight
              position={[45, 90, 45]}
              intensity={4.8}
              castShadow
              shadow-mapSize={[4096, 4096]}
              shadow-camera-near={1}
              shadow-camera-far={180}
              shadow-camera-left={-90}
              shadow-camera-right={90}
              shadow-camera-top={90}
              shadow-camera-bottom={-90}
              shadow-bias={-0.0002}
              shadow-normalBias={0.08}
            />
          ) : null}
          <pointLight position={[-5, 4, -5]} intensity={0.6} color="#24FF8E" />
          <Environment preset="city" environmentIntensity={0.45} />
          <Suspense fallback={<LoadingModel />}>
            <Bounds clip margin={1.35}>
              <group>
                {showGroundPlane ? (
                  <group position={[0, 0, 0]}>
                    <gridHelper args={[76, 38, '#d8d8d8', '#a8a8a8']} />
                    <mesh
                      rotation={[-Math.PI / 2, 0, 0]}
                      position={[0, -0.01, 0]}
                      receiveShadow
                    >
                      <planeGeometry args={[76, 76]} />
                      <meshStandardMaterial color="#505050" roughness={0.95} />
                    </mesh>
                  </group>
                ) : null}
                <Model modelUrl={modelUrl} milestones={milestones} />
              </group>
            </Bounds>
          </Suspense>
          <OrbitControls makeDefault enableDamping dampingFactor={0.08} />
        </Canvas>
      </div>
    </section>
  );
}

