  type Object3D,
} from 'three';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
  milestones?: ConstructionMilestone[];
};

type MeshSnapshot = {
  visible: boolean;
  material: MeshStandardMaterial | MeshStandardMaterial[];
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildVisibilityMap(milestones: ConstructionMilestone[]) {
  const map = new Map<string, boolean>();

  milestones.forEach((milestone) => {
    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => {
        map.set(
          nodeName,
          component.visibleWhenCompleted === false
            ? !milestone.completed
            : milestone.completed
        );
      });
    });
  });

  return map;
}

function cloneMaterial(material: MeshStandardMaterial) {
  return material.clone();
}

function tintMaterial(material: MeshStandardMaterial, visible: boolean) {
  material.transparent = false;
  material.opacity = 1;
  material.depthWrite = true;
  material.emissive.set('#000000');
  material.emissiveIntensity = 0;

  if (!visible) {
    material.color.set('#4B5563');
    material.roughness = 0.92;
    material.metalness = 0.08;
    return;
  }

  material.color.set('#D9DBE1');
  material.roughness = 0.52;
  material.metalness = 0.22;
}

function Model({
  modelUrl,
  milestones = [],
}: {
  modelUrl: string;
  milestones?: ConstructionMilestone[];
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const originalMeshes = useRef(new Map<Mesh, MeshSnapshot>());
  const visibilityByNodeName = useMemo(
    () => buildVisibilityMap(milestones),
    [milestones]
  );
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(gltf.scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [gltf.scene]);

  useEffect(() => {
    gltf.scene.traverse((object) => {
      if (!isMesh(object)) {
        return;
      }

      if (!originalMeshes.current.has(object)) {
        const originalMaterial = Array.isArray(object.material)
          ? object.material.map((material) =>
              cloneMaterial(material as MeshStandardMaterial)
            )
          : cloneMaterial(object.material as MeshStandardMaterial);

        object.material = originalMaterial;
        originalMeshes.current.set(object, {
          visible: object.visible,
          material: originalMaterial,
        });
      }

      const explicitVisibility = visibilityByNodeName.get(object.name);
      object.visible =
        explicitVisibility ??
        originalMeshes.current.get(object)?.visible ??
        true;

      if (process.env.NODE_ENV !== 'production') {
        console.debug('[digital-twin]', object.name, {
          explicitVisibility,
          visible: object.visible,
        });
      }
      object.castShadow = true;
      object.receiveShadow = true;

      const materials = Array.isArray(object.material)
        ? object.material
        : [object.material];
      materials.forEach((material) => {
        if (material instanceof MeshStandardMaterial) {
          tintMaterial(material, object.visible);
        }
      });
    });

    bounds.refresh(gltf.scene).fit();
  }, [bounds, gltf.scene, visibilityByNodeName]);

  return <primitive object={gltf.scene} position={modelOffset} />;
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

