} from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import { Suspense, useEffect, useMemo, useRef, useState } from 'react';
import {
  Box3,
  MeshStandardMaterial,
  Vector3,
  type Material,
  type Mesh,
  type Object3D,
} from 'three';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
  milestones?: ConstructionMilestone[];
};

type MeshSnapshot = {
  materials: Material[];
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildVisibilityMap(milestones: ConstructionMilestone[]) {
  const map = new Map<string, boolean>();

  milestones.forEach((milestone) => {
    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => {
        map.set(
          nodeName,
          component.visibleWhenCompleted === false
            ? !milestone.completed
            : milestone.completed
        );
      });
    });
  });

  return map;
}

function buildEnabledNameSet(milestones: ConstructionMilestone[]) {
  const names = new Set<string>();

  milestones.forEach((milestone) => {
    if (!milestone.completed) {
      return;
    }

    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => names.add(nodeName));
    });
  });

  return names;
}

function cloneMaterials(material: Material | Material[]) {
  return (Array.isArray(material) ? material : [material]).map((entry) =>
    entry.clone()
  );
}

function setNeutralMaterial(material: Material, active: boolean) {
  if (!(material instanceof MeshStandardMaterial)) {
    return;
  }

  material.transparent = !active;
  material.opacity = active ? 1 : 0;
  material.depthWrite = active;
  material.color.set(active ? '#D9DBE1' : '#D9DBE1');
  material.roughness = active ? 0.52 : 0.52;
  material.metalness = active ? 0.22 : 0.22;
  material.emissive.set('#000000');
  material.emissiveIntensity = 0;
}

function Model({
  modelUrl,
  milestones = [],
}: {
  modelUrl: string;
  milestones?: ConstructionMilestone[];
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const meshSnapshots = useRef(new Map<Mesh, MeshSnapshot>());
  const visibilityByNodeName = useMemo(
    () => buildVisibilityMap(milestones),
    [milestones]
  );
  const enabledNames = useMemo(
    () => buildEnabledNameSet(milestones),
    [milestones]
  );
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(gltf.scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [gltf.scene]);

  useEffect(() => {
    gltf.scene.traverse((object) => {
      if (!isMesh(object)) {
        return;
      }

      if (!meshSnapshots.current.has(object)) {
        const clonedMaterials = cloneMaterials(object.material);
        object.material = Array.isArray(object.material)
          ? clonedMaterials
          : clonedMaterials[0];
        meshSnapshots.current.set(object, {
          materials: clonedMaterials,
        });
      }

      const explicitVisibility = visibilityByNodeName.get(object.name);
      const isActive = explicitVisibility ?? enabledNames.has(object.name);
      object.visible = true;
      object.castShadow = true;
      object.receiveShadow = true;

      const materials = Array.isArray(object.material)
        ? object.material
        : [object.material];
      materials.forEach((material) => setNeutralMaterial(material, isActive));

      if (process.env.NODE_ENV !== 'production') {
        console.debug('[digital-twin]', object.name, {
          explicitVisibility,
          enabled: enabledNames.has(object.name),
          active: isActive,
        });
      }
    });

    bounds.refresh(gltf.scene).fit();
  }, [bounds, enabledNames, gltf.scene, visibilityByNodeName]);

  return <primitive object={gltf.scene} position={modelOffset} />;
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

