'use client';

// cspell:words drei GLTF gltf
import {
  Bounds,
  Environment,
  Html,
  OrbitControls,
  useBounds,
  useGLTF,
} from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import { Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { Box3, Vector3, type Mesh, type Object3D } from 'three';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
  milestones?: ConstructionMilestone[];
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildEnabledNameSet(milestones: ConstructionMilestone[]) {
  const names = new Set<string>();

  milestones.forEach((milestone) => {
    if (!milestone.completed) {
      return;
    }

    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => names.add(nodeName));
    });
  });

  return names;
}

function applyVisibilityToScene(
  scene: Object3D,
  enabledNames: Set<string>,
  allMappedNames: Set<string>
) {
  scene.traverse((object) => {
    if (!isMesh(object)) {
      return;
    }

    const isMapped = allMappedNames.has(object.name);
    const isEnabled = enabledNames.has(object.name);

    object.visible = isMapped ? isEnabled : false;
    object.castShadow = object.visible;
    object.receiveShadow = object.visible;

    if (process.env.NODE_ENV !== 'production') {
      console.debug('[digital-twin]', object.name, {
        isMapped,
        isEnabled,
        visible: object.visible,
      });
    }
  });
}

function Model({
  modelUrl,
  milestones = [],
}: {
  modelUrl: string;
  milestones?: ConstructionMilestone[];
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const scene = useMemo(() => gltf.scene.clone(true), [gltf.scene]);
  const enabledNames = useMemo(
    () => buildEnabledNameSet(milestones),
    [milestones]
  );
  const allMappedNames = useMemo(() => {
    const names = new Set<string>();
    milestones.forEach((milestone) => {
      milestone.components.forEach((component) => {
        component.nodeNames.forEach((nodeName) => names.add(nodeName));
      });
    });
    return names;
  }, [milestones]);
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [scene]);
  const lastSignature = useRef('');

  useEffect(() => {
    const signature = JSON.stringify({
      enabled: [...enabledNames].sort(),
      mapped: [...allMappedNames].sort(),
    });

    if (lastSignature.current === signature) {
      return;
    }

    lastSignature.current = signature;
    applyVisibilityToScene(scene, enabledNames, allMappedNames);
    bounds.refresh(scene).fit();
  }, [allMappedNames, bounds, enabledNames, scene]);

  return <primitive object={scene} position={modelOffset} />;
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

